//! Rust port of test11.cpp: invert and grayscale an RGB color.
//!
//! Usage: test11 [r g b]   (defaults: r=0.3, g=0.7, b=0.2)

mod color;
mod fmt;

use color::{ColorConverter, Rgb};
use fmt::format_cout_float;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut r: f32 = 0.3;
    let mut g: f32 = 0.7;
    let mut b: f32 = 0.2;

    if args.len() > 3 {
        r = args[1].parse().expect("invalid float for r");
        g = args[2].parse().expect("invalid float for g");
        b = args[3].parse().expect("invalid float for b");
    }

    let rgb = Rgb::new(r, g, b);

    let inverted = ColorConverter::invert(rgb);
    let grayscale = ColorConverter::grayscale(rgb);

    println!(
        "{} {} {} {} {} {}",
        format_cout_float(inverted.r),
        format_cout_float(inverted.g),
        format_cout_float(inverted.b),
        format_cout_float(grayscale.r),
        format_cout_float(grayscale.g),
        format_cout_float(grayscale.b),
    );
}

