/// Emulates C++ `std::stof`: parses the longest valid float prefix
/// (leading whitespace, sign, digits, fraction, exponent, inf/nan)
/// and aborts with `std::invalid_argument` semantics if there is none.
fn stof(s: &str) -> f32 {
    let trimmed = s.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    let rest = lower
        .strip_prefix('+')
        .or_else(|| lower.strip_prefix('-'))
        .unwrap_or(&lower);
    let sign_len = lower.len() - rest.len();

    let prefix_len = if rest.starts_with("inf") || rest.starts_with("nan") {
        // "inf"/"infinity"/"nan(...)" — take the alphabetic head.
        sign_len
            + rest
                .find(|c: char| !(c.is_ascii_alphanumeric() || c == '(' || c == ')'))
                .unwrap_or(rest.len())
    } else {
        // [digits][.digits][e[+-]digits] — longest valid numeric prefix.
        let bytes = rest.as_bytes();
        let mut i = 0;
        let mut seen_digit = false;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            seen_digit = true;
        }
        if i < bytes.len() && bytes[i] == b'.' {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
                seen_digit = true;
            }
        }
        if !seen_digit {
            abort_invalid_argument();
        }
        if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
            let mut j = i + 1;
            if j < bytes.len() && (bytes[j] == b'+' || bytes[j] == b'-') {
                j += 1;
            }
            let exp_start = j;
            while j < bytes.len() && bytes[j].is_ascii_digit() {
                j += 1;
            }
            if j > exp_start {
                i = j;
            }
        }
        sign_len + i
    };

    match trimmed[..prefix_len].parse::<f32>() {
        Ok(v) => v,
        Err(_) => abort_invalid_argument(),
    }
}

/// Mirror the C++ binary's behavior on an invalid `std::stof` argument:
/// an uncaught `std::invalid_argument` terminates the process (SIGABRT).
fn abort_invalid_argument() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
    eprintln!("  what():  stof");
    std::process::abort();
}

